019c0566-0bb3-7328-8a4a-c00b63c3f392	admin@example.com	::ffff:172.19.0.1	b2g0crzohol9hvx	pv1gx53aphpp49n	m3t3xquljpfvihq	9	DATA_DELETE	\N	\N	\N	{"data":{"Name":"Valentine's Day Make & Take Party","Description":"Join us at our Valentine's Make & Take Party from 12-3 on February 11th and create a cute craft for yourself or a loved one. Come have sweet treats while you create unique items at our all ages and kid-friendly party that celebrates and appreciates all forms of love! \\n\\nOur skilled artisans will be on hand to guide you in crafting a special Valentine's creation, ensuring a day filled with sweetness and fun.\\n\\nOur Valentine's themed crafts will include: \\nCustom mugs made in our graphics area\\nHeart shaped candy molds\\nEmbroidered personalized tote bag\\nA custom laser cut necklace, magnet or book bag charm\\n...and more!\\n\\nOne free make-&-take activity included with each General Admission ticket. Additional donations are welcome if you'd like to make more than one craft!\\n\\n*Please note, this is a timed event, so please select your desired time slot in your ticket.* ","Capacity":50,"ID_1":135,"Hours":"3","What to Bring/Wear":"Bring your creativity!\\n","Age Requirement":"All ages, under 16 accompanied by an adult","Short Description":"Join us at our Valentine's Make & Take Party and create a cute craft for yourself or a loved one. Come have sweet treats while you create unique items at our all ages and kid-friendly party that celebrates and appreciates all forms of love! \\n","Period":0,"Supply Cost":12,"Approved":true},"column_meta":{"Name":{"id":"c5yzrma7gdk0b0c","title":"Name","type":"SingleLineText","options":{}},"Description":{"id":"cx91e94c3jcsfqh","title":"Description","type":"LongText","options":{}},"Clearances Earned":{"id":"czx6uv2cm5r579v","title":"Clearances Earned","type":"SingleLineText","options":{}},"Capacity":{"id":"clamcdc516k4zgd","title":"Capacity","type":"Decimal","options":{}},"ID_1":{"id":"csu1nzdnuksrz1n","title":"ID_1","